import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"JanusVLN: Decoupling Semantics and Spatiality with Dual Implicit Memory for Vision-Language Navigation","description":"","frontmatter":{"title":"JanusVLN: Decoupling Semantics and Spatiality with Dual Implicit Memory for Vision-Language Navigation","arxiv":"2509.22548","date":"2025-09-26","authors":"Shuang Zeng, Dekang Qi, Xinyuan Chang, Feng Xiong, Shichao Xie, Xiaolong Wu, Shiyi Liang, Mu Xu, Xing Wei, Ning Guo","categories":"cs.CV, cs.RO","topics":"视觉语言导航, 隐式神经记忆, 空间几何先验","outline":[2,2]},"headers":[],"relativePath":"papers/2509.22548.md","filePath":"papers/2509.22548.md","lastUpdated":null}'),l={name:"papers/2509.22548.md"};function e(i,s,m,r,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="janusvln-decoupling-semantics-and-spatiality-with-dual-implicit-memory-for-vision-language-navigation" tabindex="-1">JanusVLN: Decoupling Semantics and Spatiality with Dual Implicit Memory for Vision-Language Navigation <a class="header-anchor" href="#janusvln-decoupling-semantics-and-spatiality-with-dual-implicit-memory-for-vision-language-navigation" aria-label="Permalink to &quot;JanusVLN: Decoupling Semantics and Spatiality with Dual Implicit Memory for Vision-Language Navigation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2509.22548" target="_blank" rel="noreferrer">2509.22548</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-09-26</td></tr><tr><td><strong>作者</strong></td><td>Shuang Zeng, Dekang Qi, Xinyuan Chang, Feng Xiong, Shichao Xie, Xiaolong Wu, Shiyi Liang, Mu Xu, Xing Wei, Ning Guo</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>在 Qwen2.5-VL 旁挂一个冻结的 VGGT 几何编码器，把两条支路的历史 KV cache（首帧 sink + 48 帧滑窗）当作固定大小的&quot;双隐式记忆&quot;，从而只用单目 RGB 就把 3D 空间线索接进 VLN，并顺带消除了重算历史帧的开销。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>abs 页给出的 HTML 版本是 <strong>v2</strong>（v1 2025-09-26，v2 2026-02-25，<strong>ICLR 2026 接收</strong>），本文按 v2 全文撰写。v2 相对 v1 补入了 HM3D-OVON、融合策略、数据组成三组附加消融与真机定量结果。作者共 10 位（abs 页在第 9 位截断），frontmatter 按 HTML 全文署名补齐；一作在阿里高德实习期间完成本工作。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLN 里&quot;记忆&quot;这件事一直是用显式结构做的：要么把走过的地方写成文字认知地图（&quot;沙发左边有一扇门&quot;），要么把历史帧原样存下来、每一步连同当前帧一起重新过一遍编码器。两条路都有具体的代价。文字地图丢掉几何——&quot;左边&quot;这个词无法表达 1.2 米还是 3 米，也无法表达朝向；反复描述同一个物体还会引入大量冗余噪声。存历史帧则是纯粹的计算浪费：第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 步要重算前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 帧，且显存随时间线性增长，长 episode 直接爆。</p><p>第二个更根本的矛盾是感知侧的。导航本质上是三维物理交互，但 VLA/VLN 模型的视觉编码器几乎清一色继承 CLIP 范式，在二维图文对上预训练。这类编码器擅长&quot;这是什么&quot;，不擅长&quot;它在哪、多远、和别的东西什么关系&quot;。而二维图像本身其实携带了大量三维线索（透视、遮挡、结构），人可以从一张静态照片里读出深度布局，现有模型却把这条现成的信息通道浪费了。论文要解决的正是这两件事的交集：<strong>在不引入深度相机的前提下，把空间几何补进来，同时让记忆的大小与计算量都不随时间增长。</strong></p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>三类前作各自碰到了不同的墙。</p><p><strong>显式语义地图</strong>这一类（用文字节点与关系边构建认知地图）好处是可解释、可被 LLM 直接读，但纯文本无法精确传达空间关系与朝向，且随着导航时间增长，地图变成一堆碎片化的重复描述，模型很难从中检索到关键信息。</p><p><strong>存历史帧</strong>这一类（NaVid / Uni-NaVid / NaVILA / StreamVLN 这条线）把观测序列直接喂给视频 VLM，语义能力强，但每步都要重处理整段历史，计算冗余极大；而且它们通常只用一路前视 RGB，空间理解薄弱，于是只能靠堆数据来补——StreamVLN 用了约 2633 万训练样本，NaVILA 用了约 1313 万。</p><p><strong>引入 3D 数据</strong>这一类（RGB-D、点云输入，如 g3D-LF、NaVid-4D）确实补上了几何，但依赖额外且昂贵的传感器，在很多真实部署场景里根本没有深度相机可用。</p><p>还有一条更新的线：用前馈式 3D 几何基础模型（VGGT 这类，从多视图 RGB 直接回归点图）从视频里抽空间信息。它不需要深度传感器，但<strong>原生 VGGT 每来一帧都要把整个序列重新前向一次</strong>——论文测得 48 帧就能在 48G 显存上 OOM，推理时间随帧数指数增长，完全无法用于流式导航。</p><p>于是缺口很清楚：需要一个既能拿到 3D 几何先验、又能像 KV cache 一样增量更新的机制。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是一个类比观察：人在陌生环境里导航时，并不会在脑子里存一串原始画面，也不会写一份文字地图，而是维持某种压缩过的场景表征。而神经科学里&quot;左脑语义、右脑空间&quot;的半球分工提示这两类信息可能本来就该分开存。这给出了&quot;双记忆&quot;的动机。</p><p>第二步是问：这个&quot;压缩表征&quot;在 transformer 里对应什么？答案几乎是现成的——<strong>注意力模块输出的 KV 就是被网络深度加工过的历史抽象</strong>。存 KV 而不是存原图，等于把&quot;记忆&quot;从像素级搬到了表征级，且天然支持增量：新帧只需要对已有的 KV 做交叉注意力，不必重算历史。</p><p>第三步是记忆大小。全量 KV 依然线性增长。这里可以直接借用长上下文 LLM 里已被反复验证的两个事实：滑动窗口能覆盖近期上下文；而最初几个 token 会持续吸走大量注意力（attention sink），把它们扔掉会显著掉性能。于是&quot;首若干帧永久保留 + 最近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 帧 FIFO&quot;这个混合结构就被推出来了。</p><p>第四步是几何从哪来。既然不能加深度相机，就得从 RGB 里回归——VGGT 正好是在&quot;像素-三维点云对&quot;上预训练的，它的中间特征天然带 3D 先验，而这恰恰是 Qwen2.5-VL 的视觉编码器所缺的那一维。把 VGGT 的 encoder + fusion decoder 摘出来当第二条支路，并同样施加双窗口 KV 缓存，就同时解决了几何与效率。</p><p>最后一步是融合。两条支路的特征形状可以通过 Qwen2.5-VL 自带的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 空间合并策略对齐，那么最简单的融合就是加权相加 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9989em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">MLP</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。作者试过 concat 与 cross-attention，最后发现最简单的加法最好。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p><strong>历史不该被存成图片，也不该被写成文字，而应该存成网络已经算好的 KV</strong>——这样它既是压缩的，又是可直接被注意力检索的，还天然支持增量更新。第二个直觉是：语义和几何应该由两个<strong>预训练目标不同</strong>的编码器分别提供，因为图文对比学习学不出三维结构，而点云回归学不出开放词表语义；把两个冻结编码器的 KV 并列缓存，就得到了一个&quot;左脑 + 右脑&quot;的双记忆。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 R2R-CE 的一条 episode 为例。动作空间是 <code>{前进 0.25 m, 左转 30°, 右转 30°, 停止}</code>。</p><ol><li><strong>双编码器</strong>。当前帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 同时送进两条支路：Qwen2.5-VL 的语义视觉编码器得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，VGGT 的 encoder + fusion decoder 得到几何 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。两个编码器<strong>全程冻结</strong>。</li><li><strong>双隐式记忆</strong>。每条支路都维护 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">initial</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sliding</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">initial</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 永久保留最初 8 帧的 KV（attention sink），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sliding</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是容量 48 的 FIFO 队列。新帧只做 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">Decoder</span></span><span class="mopen">(</span><span class="mord text"><span class="mord">CrossAttn</span></span><span class="mopen">(</span><span class="mord text"><span class="mord">Encoder</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mclose">))</span></span></span></span>，不重算历史。LLM 侧同样只保留初始窗与滑窗的 KV。</li><li><strong>对齐与融合</strong>。用 Qwen2.5-VL 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 空间合并把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 压到与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9989em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span> 同形，再两层 MLP 投影后加权相加：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9989em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MLP</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2</span></span></span></span>。</li><li><strong>决策</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与指令文本嵌入一起送进 Qwen2.5-VL 7B 主干，输出下一个低层动作。</li><li><strong>训练</strong>。只微调 LLM（lr 2e-5）与投影层（lr 1e-5），一个 epoch。额外数据是 ScaleVLN 子集 155K 轨迹（约 920.7 万图像-动作对）与用 DAgger 在 R2R-CE/RxR-CE 上采的 14K 轨迹（约 148.5 万对），合计约 1069 万训练样本。</li><li><strong>部署</strong>。真机用宇树 Go2 + Insta360 X5 前视 RGB，模型跑在远端 A10 上，结果回传执行。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很轻，但有两处值得算一算。</p><p><strong>其一，记忆规模与计算量的量级。</strong> 记 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">n</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">init</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">n</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">slide</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">48</span></span></span></span>，则任意时刻缓存的帧数恒为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">56</span></span></span></span>，与 episode 长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 无关。相比之下，原生 VGGT 在第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 步要对整段序列做全注意力，代价是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>；论文实测 8 帧时 268 ms、32 帧时 1549 ms，比值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1549/268</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5.8</span></span></span></span> 而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">32/8</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span>，说明实际增长介于线性与平方之间（有常数项与显存搬运的影响）。缓存版对应的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord">1</span><span class="mclose">)</span></span></span></span> 的每帧代价：8 帧 82 ms、32 帧 149 ms、48 帧 195 ms、64 帧 244 ms，随记忆大小近似线性且斜率很小（约 3.3 ms/帧）。由此可自行推出一条论文没写的结论：<strong>在 48 帧记忆下，几何支路的每步开销约 195 ms，这已经占据了 A10 上单步决策的相当一部分</strong>，也就是说&quot;效率优势&quot;是相对原生 VGGT 而言的，绝对延迟依然不低。</p><p><strong>其二，融合式 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9989em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MLP</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的性质。</strong> 这是一个残差注入：几何特征以固定权重加到语义特征上，不改变 token 数量，也不改变主干的输入维度。它的好处是主干可以在&quot;完全忽略几何&quot;（把 MLP 学成零映射）与&quot;重度依赖几何&quot;之间平滑过渡，训练不易崩。代价是几何信息在<strong>每一个 token 位置上都被同等强度注入</strong>，无法按位置自适应。表 7 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span> 扫描（0.5 → 50.4 SR、0.2 → 52.8、0.1 → 50.2）呈现明显的单峰，且两侧下降幅度接近（−2.4 / −2.6），这与&quot;注入太强会污染语义、太弱等于没加&quot;的直觉一致。CrossAttn 融合（52.1）几乎追平加法（52.8），Concat 最差（49.4）。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：只用单目 RGB 能不能打过用了深度/全景/里程计的方法？</strong> 能。R2R-CE Val-Unseen 上 JanusVLN 达到 NE 4.78 / OS 65.2 / SR 60.5 / SPL 56.8，相对使用全景+里程计+深度的多输入方法 SR 高出 10.5–35.5；相对使用额外 3D 深度数据的方法（g3D-LF、NaVid-4D 一类）高出 12.6–16.7。RxR-CE 上 NE 6.06 / SR 56.2 / SPL 47.5 / nDTW 62.1。</p><p><strong>问题二：相对同为 RGB-only 的强基线呢？</strong> 这是更严格的对照。R2R-CE 上 StreamVLN 用约 2633 万样本拿到 56.9 SR，JanusVLN 用约 1069 万样本拿到 60.5，即<strong>用不到一半的数据高出 3.6 点</strong>。更干净的一格是零额外数据版本：JanusVLN* 用 0 条外部数据拿到 52.8 SR / 49.2 SPL，超过用了 1257 万样本的 NaVILA*（49.7 / 45.5）。</p><p><strong>问题三：双记忆的两半各值多少？</strong> 表 3：完整 52.8 SR / 49.2 SPL；去掉空间隐式记忆 47.0 / 40.9；去掉语义隐式记忆 45.5 / 40.0；两个都去掉塌到 24.8 / 16.8。作者用&quot;移除语义记忆使 SR 下降 13.8%&quot;描述，这是相对下降（52.8→45.5）。</p><p><strong>问题四：增益是来自 3D 先验还是来自&quot;多加了一个编码器&quot;？</strong> 表 4 是全文最重要的对照，也是我认为写得最好的一处：额外挂 DINOv2 得到 47.5 SR、额外挂 SigLIP 2 得到 47.9、额外挂<strong>随机初始化的 VGGT</strong> 得到 47.2，三者与&quot;不挂额外编码器&quot;的 47.0 几乎无差别；只有挂上<strong>预训练的 VGGT</strong> 才跳到 52.8。随机初始化 VGGT 这一行直接排除了&quot;参数量变多&quot;这一替代解释。</p><p><strong>问题五：记忆结构本身有效吗？</strong> 表 5：同样 8 帧记忆，原生 VGGT 268 ms / 50.2 SR，缓存版 82 ms / 50.5 SR——<strong>更快且略好</strong>。记忆从 8 增到 48 时性能单调改善（50.5→51.7→52.8），64 帧时 SR 回落到 52.3（SPL 略升到 49.4），作者据此认为 48 帧饱和。去掉初始窗 KV 后掉到 51.0 SR，证实 attention sink 有实效但幅度不大（1.8 点）。</p><p><strong>问题六：泛化与真机。</strong> HM3D-OVON val-unseen 上 SR 从此前最好的 40.8 提到 44.9，SPL 从 12.1–19.8 区间提到 31.7。真机用 25 条指令 × 3 次重复，成功判据是停在目标 1 米内；作者报告需要空间理解的任务上相对无空间记忆版本提升 23.6%，但<strong>主结果只有图 6 的柱状图，没有数值表</strong>，故不复述绝对成功率。</p><p><strong>失败分析（附录 D）</strong>：两类主要失败——偏航后无法纠正（DAgger 采的非最优轨迹数据量不足），以及停车过早（作者归因于 VGGT 的空间信息<strong>缺乏真实尺度</strong>，导致距离估计不准）。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：JanusVLN 把 VLN 的记忆从&quot;显式的文字地图或历史帧&quot;改成&quot;两条冻结编码器的 KV cache&quot;，其中语义来自 Qwen2.5-VL 的视觉编码器、几何来自在点云上预训练的 VGGT。记忆用&quot;首 8 帧永久 sink + 48 帧 FIFO 滑窗&quot;的混合结构固定大小，因此计算与显存都不随导航时长增长，几何支路单步开销从原生 VGGT 的 268–1549 ms 降到 82–195 ms。R2R-CE Val-Unseen 60.5 SR、RxR-CE 56.2 SR，用不到 StreamVLN 一半的训练数据高出 3.6 点；零额外数据版本也超过用了千万级样本的 NaVILA。最有说服力的证据是表 4：换成 DINOv2、SigLIP 2 或随机初始化的 VGGT 都只值 0.2–0.9 点，只有预训练 VGGT 值 5.8 点，干净地把&quot;3D 先验&quot;与&quot;加参数&quot;分开了。最大的隐患是&quot;去掉空间记忆&quot;这一行实际上等于&quot;去掉整个 VGGT 支路&quot;，记忆机制本身从未被单独消融。</p><p><strong>3 句话版</strong>：把历史存成 KV 而不是存成图或文字，记忆就自动变成定长且增量可更新的。再挂一条几何预训练的支路，单目 RGB 也能拿到 3D 线索。真正被验证的是&quot;几何预训练有用&quot;，而&quot;隐式记忆比显式记忆好&quot;这一半的证据要弱得多。</p><p><strong>1 句话版</strong>：VLN 的记忆问题，一半是表示问题（存什么），另一半是编码器的预训练目标问题（几何还是语义）。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>VGGT 从单目 RGB 回归出的几何 token 携带了导航所需的度量空间信息。</strong> 全文的第一贡献（&quot;用 RGB 补上 3D 感知，不需要深度传感器&quot;）完全压在这条上。</p><p>它在实践中至少部分不成立，而且论文自己给出了证据。附录 D 的失败分析明确写道：JanusVLN 有一类主要失败是&quot;看到目标就过早停车、没进入成功半径&quot;，作者的解释是 <strong>VGGT 的空间信息缺乏真实世界尺度（lacks real-world scale），导致距离估计不准</strong>。这正是单目几何回归的结构性缺陷——从单张 RGB 恢复的点图在尺度上是不确定的，只有相对结构可靠。而 VLN 的成功判据恰恰是一个绝对距离阈值（停在目标 3 米内 / 真机 1 米内）。</p><p>这条假设的失效范围可以被更精确地界定：涉及<strong>相对关系</strong>的指令（&quot;最远的那把椅子&quot;、&quot;绿植旁边&quot;、&quot;最右边的房子&quot;）只需要序关系，尺度不确定不影响；而涉及<strong>绝对距离</strong>的判断（何时该停、还有多远）会系统性受损。论文的图 7 恰好只测了前一类——它统计的是含 &quot;farthest/nearest/leftmost/front/back&quot; 等词的指令，并报告在这类指令上优势更大。也就是说，<strong>论文展示优势的那个子集，正好是这条脆弱假设不生效的子集</strong>。</p><p>缺的证据很具体：把 VGGT 输出的点图与真值深度做一次尺度对齐误差分析，或者报告&quot;停止动作的距离误差分布&quot;。两者都没有。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要重训 7B 模型的方案：<strong>把&quot;空间记忆&quot;与&quot;空间编码器&quot;分开。</strong></p><p>论文表 3 的 &quot;w/o Spatial Implicit Memory&quot; 行（47.0 / 40.9）与表 4 的 &quot;w/o extra encoder&quot; 行（47.0 / 40.9）<strong>数值逐位相同</strong>，说明这两行是同一个实验：去掉的不是记忆，而是整条 VGGT 支路。因此&quot;空间记忆&quot;这个机制本身从未被单独测过。</p><ul><li><strong>实现</strong>：三个变体，全部基于已训好的 JanusVLN* 权重，只改推理期的几何支路记忆策略。(a) 完整双窗口（8 sink + 48 滑窗）；(b) 只保留当前帧、几何支路无任何历史 KV（即 VGGT 退化成单帧编码器）；(c) 只保留 48 帧滑窗、去掉 sink（论文已有此行，51.0 SR，可作校验点）。</li><li><strong>测量</strong>：R2R-CE Val-Unseen 的 NE / OS / SR / SPL，以及每步几何支路延迟。</li><li><strong>判据</strong>：若 (b) 掉到 47 附近，说明几何<strong>记忆</strong>确实重要；若 (b) 仍在 51–52，则几何支路的价值几乎全部来自&quot;单帧 3D 先验&quot;，双窗口记忆只是一个效率优化而非性能来源，论文的第一贡献应被重述。(c) 已知为 51.0，可用来校验实验设置是否正确复现。</li></ul><p>这个实验的成本极低（不训练、只改推理），但它检验的正是全文标题里的那个词。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对&quot;双隐式记忆是一个新范式&quot;这一主张，最强的替代解释是：<strong>JanusVLN 的增益基本可以由&quot;一个额外的、预训练目标互补的冻结编码器&quot;解释完，与记忆无关。</strong></p><p>支撑这个解释的证据全部来自论文自己。第一，如上所述，&quot;去掉空间记忆&quot;与&quot;去掉额外编码器&quot;是同一行。第二，表 4 显示挂 DINOv2/SigLIP 2 只值 0.5–0.9 点，挂预训练 VGGT 值 5.8 点，差别完全在编码器的预训练目标上，与是否缓存 KV 无关。第三，表 5 显示缓存版相对原生 VGGT 的性能几乎持平（8 帧：50.5 vs 50.2；32 帧：51.7 vs 51.2），差距在噪声量级——也就是说 KV 缓存<strong>没有带来性能，只带来了速度</strong>。第四，去掉 attention sink 只掉 1.8 点，而 sink 正是&quot;隐式记忆&quot;这套叙事里最独特的成分。</p><p>把这四条放在一起，一个更朴素的描述是：JanusVLN = Qwen2.5-VL + 冻结 VGGT 残差注入（性能来源）+ 双窗口 KV 缓存（效率来源）。这个描述能解释所有已报告的数字，且不需要&quot;隐式神经记忆是新范式&quot;这个更强的主张。</p><p><strong>判决实验</strong>：跑一个&quot;无记忆、全重算&quot;的上界版本——几何支路每步对完整历史做原生 VGGT 前向（慢，但只在短 episode 上做得动，比如截断到 32 步），语义支路保持不变。若它与完整 JanusVLN 在同长度 episode 上性能相当（表 5 的 32 帧那一行已经暗示了这一点：51.2 vs 51.7），则&quot;固定大小记忆&quot;的贡献被确证为纯效率；若它明显更好，则说明双窗口是在牺牲性能换速度，论文应报告这个代价。无论哪个结果，都比现在这组消融更有信息量。</p><p>另有一个次级观察值得记入：表 8 的 &quot;ScaleVLN &amp; DAgger&quot; 行 SPL 记 56.6，而表 1 的 JanusVLN 行同配置记 56.8，两处不一致（其余四个指标一致），属抄录误差。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：JanusVLN 的空间记忆是<strong>尺度不定</strong>的——VGGT 从单目 RGB 回归的点图只保证相对结构，作者自己把停车过早归因于此。同时，它的记忆是<strong>时间局部</strong>的：48 帧滑窗覆盖不了一条上百步的轨迹，早期看到的房间在滑窗滑过之后就只剩 8 帧 sink 里那点残影。这两条局限有一个共同的根源：几何信息被当成&quot;逐帧特征&quot;而不是&quot;一个在世界坐标系里累积的量&quot;。</p><p><strong>(b) 可借鉴的相邻工具</strong>：把机器人自身的<strong>动作序列</strong>当作尺度与位姿的免费监督。VLN-CE 的动作是量化的（前进恰好 0.25 米、转向恰好 30°），这意味着任意两帧之间的相对位姿变换是<strong>已知的</strong>，且带真实米制单位。这与视觉里程计/SLAM 里用运动约束标定单目尺度是同一件事，只不过这里运动是被自己发出的、无噪声的。可借的工具有三样：单目 VO 的尺度恢复（用已知基线求解尺度因子）、隐式场景表征里的增量式融合（把新帧的点图对齐到一个持久的世界系表征而非帧系表征）、以及记忆压缩里的&quot;按空间而非按时间&quot;淘汰准则（保留覆盖不同空间区域的 KV，而不是保留最近的 KV）。</p><p><strong>(c) 第一个实验长什么样</strong>：在训练时增加一个几乎零成本的辅助损失——用已知的动作序列构造帧对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 及其真值相对位姿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>（由动作累积得到），要求从两帧的几何 token 上用一个轻量头回归出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 的平移<strong>米制模长</strong>。这一项不需要任何新标注，因为动作本来就在训练数据里。评价三条：其一，回归误差是否随训练下降到亚米级（检验尺度是否可从动作恢复）；其二，加了该损失后，&quot;停止动作的距离误差分布&quot;是否收窄（这正是论文失败分析里那一类错误）；其三，SR/SPL 是否提升，尤其在 RxR-CE 这种长指令、长轨迹的集合上。如果第二条成立而第三条不成立，说明尺度只是失败原因之一；如果两条都成立，那么&quot;用自身动作给单目几何标定尺度&quot;就是一条比&quot;再挂一个编码器&quot;便宜得多的改进路径，且它同时给出了把记忆从时间窗改造成空间图的坐标基础。</p>',61)])])}const u=a(l,[["render",e]]);export{o as __pageData,u as default};
